      },
      "required": [
        "run",
        "job",
        "eventTime",
        "producer",
        "schemaURL"
      ]
    },
    "Run": {
      "type": "object",
      "properties": {
        "runId": {
          "description": "The globally unique ID of the run associated with the job.",
